// src/components/Navbar.js
import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar = ({ isAuthenticated, user, onLogout }) => {
  const [showDropdown, setShowDropdown] = useState(false);
  const location = useLocation();

  // Only use in-page anchors if we are on the home page
  const inHomePage = location.pathname === '/';

  const toggleDropdown = () => setShowDropdown(!showDropdown);

  const handleLogout = () => {
    setShowDropdown(false);
    onLogout();
  };

  return (
    <nav className="navbar">
      {/* Left: Logo */}
      <div className="navbar-left">
        <Link to="/" className="logo">RealTimeHumanDetect</Link>
      </div>

      {/* Center: Navigation links */}
      <div className="navbar-center">
        {inHomePage ? (
          <>
            <a href="#home">Home</a>
            <a href="#about">About</a>
            <a href="#features">Features</a>
            <a href="#contact">Contact</a>
          </>
        ) : (
          <>
            {/* If not on home page, redirecting to home will show the sections */}
            <Link to="/#home">Home</Link>
            <Link to="/#about">About</Link>
            <Link to="/#features">Features</Link>
            <Link to="/#contact">Contact</Link>
          </>
        )}
      </div>

      {/* Right: Authentication or user profile with dropdown */}
      <div className="navbar-right">
        {isAuthenticated ? (
          <div className="user-profile">
            <span
              className="user-name"
              onClick={toggleDropdown}
              style={{ cursor: 'pointer' }}
            >
              {user && user.name}
            </span>
            {showDropdown && (
              <div className="dropdown-menu">
                <button onClick={handleLogout}>Logout</button>
              </div>
            )}
          </div>
        ) : (
          <div className="auth-links">
            <Link to="/signin">Sign In</Link>
            <Link to="/signup">Sign Up</Link>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
